<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import PageHero from '../components/PageHero.vue'; import NewsCard from '../components/NewsCard.vue'; import { findRecord } from '../data/contentLookup'; import { news } from '../data/news'; const route=useRoute();const item=computed(()=>findRecord(news,route.params.id));const related=computed(()=>news.filter(record=>record.id!==route.params.id).slice(0,2))</script>
<template><PageHero :title="item ? item.title : '新闻内容不存在'" description="新闻活动详情" :image="item?.image" /><section class="section"><div class="shell"><div v-if="item"><article class="detail-main"><p class="card-meta">{{ item.category }} · {{ item.date }} · {{ item.author }}</p><h2>{{ item.title }}</h2><img :src="item.image" :alt="item.title" /><p>{{ item.content }}</p><p>浏览次数：{{ item.views }}（演示）</p></article><div class="section-heading" style="margin-top:48px"><h2>相关新闻</h2></div><div class="news-list"><NewsCard v-for="record in related" :key="record.id" :item="record" /></div></div><div v-else class="empty-state"><h2>内容不存在</h2><RouterLink class="button" to="/news">返回新闻列表</RouterLink></div></div></section></template>
